const FMT_RU: Record<string, string> = { PNG: 'PNG', JPG: 'JPG', WebP: 'WebP', BMP: 'BMP', SVG: 'SVG', GIF: 'GIF', ICO: 'ICO' };

/** Russian text for "X to Y" converter presets. */
export function converterRu(from: string, to: string): ToolText {
  const a = FMT_RU[from] ?? from;
  const b = FMT_RU[to] ?? to;
  return {
    name: `${a} в ${b}`,
    description: `Конвертируйте ${a} в ${b} прямо в браузере — пакетно и без загрузки на сервер.`,
    about: `Превращайте файлы ${a} в изображения ${b} локально на вашем устройстве. Выберите один или много файлов, настройте качество и скачайте результаты по одному или все сразу ZIP-архивом.`,
    title: `Конвертер ${a} в ${b} — бесплатно, приватно, офлайн`,
    keywords: [`${a.toLowerCase()} в ${b.toLowerCase()}`, 'конвертировать', 'перевести'],
  };
}
